"""Five independently complete lessons; reuse owned fraction-model definitions."""
import json,copy
from pathlib import Path
BASE=json.loads((Path(__file__).parent.parent/'production-v2/catalogue.json').read_text())[:5]
def row(n,d,label,colour='teal'):return dict(n=n,d=d,label=label,colour=colour)
def cue(chapter,text,*,role='explanation',equation=None,rows=None,note='',pause=.35,**kw):
 return dict(chapter=chapter,text=text,role=role,equation=equation,rows=rows or [],note=note,pause=pause,**kw)
def predict(text,source,title='Make a prediction',pause=3):
 c=copy.deepcopy(source);c.update(chapter=title,text=text,role='prediction',pause=pause,hide_equation=True,hide_labels=True);return c
CONFIG=[
 dict(slug='comparing-ordering',title='Comparing and Ordering Fractions',section='meaning',goal='Compare and order fractions using models and reasoning.',criteria=['Compare equal-sized parts','Explain comparisons using models','Order fractions on a number line'],hook="Two friends both claim they've chosen the bigger share of the same-sized chocolate bar. How could a picture settle this delicious disagreement?",start=[row(3,4,'A share of a chocolate bar'),row(1,2,'Another share of the same-sized bar','gold')],goal_speech="Today, we're learning to compare and order fractions, so we can explain which amount is greater, smaller or equal.",criteria_speech=["You'll compare shares fairly, using wholes of the same size.","You'll use a picture or equivalent fractions to explain your choice, rather than guessing from the numbers.","And you'll put fractions in order by finding their positions on a number line."],closing="Our goal was to compare and order fractions. You can compare equal parts, explain a fair comparison, and read a number line. Which model will help you explain your next answer? Try the practice on Math Magic."),
 dict(slug='equivalent',title='Equivalent Fractions',section='equivalent',goal='Recognise, create and explain equivalent fractions.',criteria=['Spot equal amounts in different models','Create equivalent fractions','Simplify without changing the value'],hook="Can a share change its name without getting any bigger? Imagine dividing your half of a ribbon into smaller pieces. Have you somehow gained more ribbon?",start=[row(1,2,'A half-length share'),row(2,4,'The same share with more divisions','gold')],goal_speech="Today, we're learning to recognise, create and explain equivalent fractions: different names for exactly the same amount.",criteria_speech=["You'll recognise equal amounts, even when the pictures have different numbers of pieces.","You'll create a new fraction name by changing both numbers fairly.","You'll also simplify a fraction, and use a model to explain why its value stays the same."],closing="We set out to recognise, create and explain equivalent fractions. You can split or group equal parts, change both numbers together, and check that the amount stays the same. How many names can you find for one half? Explore the practice on Math Magic."),
 dict(slug='mixed-improper',title='Mixed Numbers and Improper Fractions',section='mixed',goal='Represent and convert mixed numbers and improper fractions.',criteria=['Build wholes from equal parts','Convert between the two forms','Check the value with a model'],hook="Imagine sharing eleven quarter-sized pieces among a group. Counting pieces is easy, but how many whole units could you build? There's more than one way to name this amount!",start=[row(11,4,'Eleven equal quarter-pieces')],goal_speech="Today, we're learning to represent and convert mixed numbers and improper fractions, without changing the amount they describe.",criteria_speech=["You'll group equal pieces to see complete wholes and any extra part.","You'll turn an improper fraction into a mixed number, and go back the other way.","You'll check that both names match the same model or number-line position."],closing="Our goal was to connect mixed numbers and improper fractions. You can build wholes, count the leftover parts, and convert in either direction. Before calculating, what would your amount look like? Try drawing it, then practise on Math Magic."),
 dict(slug='adding-subtracting',title='Adding and Subtracting Fractions',section='addsub',goal='Add and subtract fractions using equal-sized parts.',criteria=['Choose a common size of part','Add or subtract and simplify','Explain the result with a model'],hook="You're making a snack mix. One scoop fills half a cup, and another fills a quarter of a cup. Will they fill the cup, spill over, or leave some space?",start=[row(1,2,'Half a cup'),row(1,4,'A quarter of the same cup','gold')],goal_speech="Today, we're learning to add and subtract fractions using visual models and number strategies. The secret is working with equal-sized parts.",criteria_speech=["You'll make the parts the same size when the denominators are related.","You'll add or subtract carefully, and simplify your answer when you can.","You'll use a model, a number line or an estimate to explain why your answer makes sense."],closing="Our goal was to add and subtract fractions. Make the parts match, combine or remove them, then simplify and check. What would you draw first for your next calculation? Try the fraction practice on Math Magic. The separate L C M video is optional extension work."),
 dict(slug='word-problems',title='Fraction Word Problems',section='problems',goal='Model everyday fraction problems and explain a suitable strategy.',criteria=['Identify the whole and the unit','Choose and model a strategy','Calculate, explain and check'],hook="A recipe, a ribbon and a walking track all hide fraction puzzles. Your first job isn't to grab the numbers. It's to discover what the story is really asking!",start=[row(1,2,'A recipe amount'),row(1,4,'Another recipe amount','gold')],goal_speech="Today, we're learning to interpret everyday fraction problems, choose a suitable strategy, and explain a solution that makes sense.",criteria_speech=["You'll identify the whole and the unit, so you know what each fraction describes.","You'll choose an operation and make a model before you calculate.","You'll explain your answer with its unit, then check it against the story."],closing="Our goal was to solve and explain everyday fraction problems. Identify the whole, model the relationship, calculate and check the unit. Could you invent a fraction story about your own day? Give it a try, then explore the practice on Math Magic.")
]
LESSONS=[]
for config,base in zip(CONFIG,BASE):
 l=copy.deepcopy(config);old=copy.deepcopy(base['beats']);beats=[]
 beats.append(cue('A fraction puzzle for you',l['hook'],role='hook',rows=l['start'],hide_labels=True,pause=.7))
 beats.append(cue('Today’s Learning Goal',l['goal_speech'],role='goal',rows=l['start'],display=l['goal'],pause=.6))
 for i,t in enumerate(l['criteria_speech']):beats.append(cue('By the end of this lesson, you will be able to…',t,role='criteria',criteria=l['criteria'],active=i,pause=.2))
 # Establish equal wholes, denominator and numerator before symbolic work.
 beats.append(cue('Start with the whole',"First, choose one whole. Its parts must be equal in size. The outline of the model shows the entire whole, not just the coloured share.",rows=[row(0,4,'One whole divided into four equal parts')],hide_labels=True,pause=.5))
 beats.append(cue('Connect the picture to the numbers',"Here, three equal parts are chosen out of four. The top number, the numerator, counts chosen parts. The bottom number, the denominator, tells how many equal parts make the whole.",equation=[[3,4]],rows=[row(3,4,'Three of four equal parts')],pause=.6))
 for i,b in enumerate(old[1:-1],1):
  b['pause']=.35;b['role']=b.get('role','explanation');b['source_beat']=i
  if l['section']=='addsub' and i in [13,14,15]:continue # Keep LCM separate.
  # Progressive questions precede the first and more demanding worked examples.
  slots={'meaning':{4:("Look at these two equal-sized wholes. Which has the greater coloured share? Count the quarter-sized pieces before you decide.",'Example 1: compare matching parts'),7:("Now the pieces have different sizes. Predict whether three quarters or one half is greater. Could you describe the half using quarters?",'Example 2: make the pieces match')},
  'equivalent':{1:("If every half is split into two equal pieces, what will happen to the coloured amount? Predict its new fraction name.",'Example 1: rename a half'),4:("Can you give three fifths a new name with twenty equal parts in the whole? Think about what changes and what must stay unchanged.",'Example 2: rename three fifths')},
  'mixed':{1:("How many complete wholes can you build from eleven quarters? Group four pieces at a time, and notice any pieces left over.",'Example 1: build the wholes'),6:("How could you count all the fifth-sized pieces in three and two fifths? Remember that each whole contains five fifths.",'Example 2: count all the parts')},
  'addsub':{1:("What is two sevenths plus three sevenths? Think about the size of each piece, then predict the number of pieces altogether.",'Example 1: combine matching parts'),3:("For half a cup plus a quarter of a cup, what size of piece could you use for both amounts? Predict the total.",'Example 2: rename, then add')},
  'problems':{1:("A recipe uses half a cup of oats and a quarter of a cup of nuts. What operation fits the question: how much altogether?",'Example 1: understand the recipe'),4:("A ribbon is two metres long. We cut off three quarters of a metre. Will the remaining length be more or less than one metre?",'Example 2: think about the ribbon')}}
  if i in slots[l['section']]:
   text,title=slots[l['section']][i];bq=predict(text,b,title)
   if l['section']=='addsub':bq['rows']=l['start'] if i==3 else [row(2,7,'Two sevenths'),row(3,7,'Three sevenths','gold')]
   if l['section']=='problems' and i==4:bq['rows']=[row(8,4,'Two metres'),row(3,4,'The length cut off','gold')]
   beats.append(bq)
  # Give important connections an explanatory hold, not a rushed rule.
  additions={
   ('meaning',4):"We can count these pieces directly because their sizes match. With the same denominator and equal-sized wholes, more chosen parts means more of the whole.",
   ('meaning',6):"It can be tempting to choose the fraction with the bigger denominator. But dividing the same whole into more pieces makes each piece smaller, not bigger.",
   ('meaning',7):"Only the divisions have changed. The half still covers exactly the same length. Two quarters and one half are equivalent names for that amount.",
   ('equivalent',2):"Notice the coloured length stays fixed while the boundaries change. We aren't adding ribbon; we're choosing a new way to count equal-sized pieces.",
   ('equivalent',4):"The whole has four times as many pieces, and the chosen share has four times as many pieces too. Changing both counts together keeps the share unchanged.",
   ('equivalent',9):"Adding one to the top and bottom gives two thirds, not another name for one half. Compare the equal-length bars: the coloured amounts are different.",
   ('mixed',5):"The remainder counts extra quarter-sized pieces. It doesn't become the denominator. A picture helps you see two complete wholes and three quarters of the next one.",
   ('mixed',8):"Counting in fifths doesn't change the whole or the amount. It simply replaces the whole-number groups with a single count of equal pieces.",
   ('addsub',2):"Adding denominators would rename our pieces as fourteenths, even though we never cut the pieces smaller. Keep the piece size, and count the chosen pieces.",
   ('addsub',4):"Two quarters plus one quarter is three quarters. That's more than half a cup but less than a full cup, which agrees with the picture.",
   ('addsub',6):"Six eighths with one eighth removed leaves five eighths. The result is smaller than three quarters, so our subtraction passes a quick sense check.",
   ('problems',3):"A useful answer tells the amount and its unit: three quarters of a cup. Compare it with the ingredients to check that nothing has disappeared or been counted twice.",
   ('problems',7):"The three quarters refers to one metre, not three quarters of the two-metre ribbon. Naming the unit clearly prevents a very different calculation."
  }
  # Each deliberate misconception is labelled; no false equation is presented as true.
  if (l['section'],i) in [('meaning',6),('equivalent',9),('addsub',2),('problems',7)]:b['role']='misconception'
  if b['role']=='question':b['pause']=5;b['chapter']='Your turn: think for five seconds';b['hide_equation']=False;b['note']='Think for five seconds, then explain your reasoning.'
  beats.append(b)
  extra=additions.get((l['section'],i))
  if extra:
   e=copy.deepcopy(b);e.update(text=extra,chapter='Why does that work?' if b['role']!='misconception' else 'A useful mistake to notice',pause=.65);beats.append(e)
  if l['section']=='mixed' and i==8:
   beats.append(cue('A common mix-up',"A mixed number isn't made by adding its whole number to its numerator. Two and three quarters is not five quarters. The two wholes already contain eight quarters.",role='misconception',equation=[[2,3,4],'≠',[5,4]],rows=[row(11,4,'Two wholes and three quarters'),row(5,4,'Only one whole and one quarter','gold')],pause=.65))
   beats.append(cue('Count the wholes before the extra parts',"Eight quarters plus three quarters is eleven quarters. That's why we multiply the whole number by the denominator, then add the extra numerator.",equation=[[2,3,4],'=',[11,4]],rows=[row(11,4,'Eleven quarters make the original amount')],pause=.65))
  if l['section']=='mixed' and i==11:
   beats.append(cue('Mixed numbers have positions too',"A number line helps us check amounts beyond one. Two and one half is ten quarter-steps from zero. Two and three quarters is one quarter-step further to the right.",equation=[[2,1,2],'<',[2,3,4]],line={'d':4,'points':[10,11],'maximum':3},pause=.65))
 beats.append(cue('Look what you can do now',l['closing'],role='recap',display=l['goal'],criteria=l['criteria'],pause=2))
 l['beats']=beats;l['file']='videos/fractions-2026/'+l['slug'];LESSONS.append(l)
assert len(LESSONS)==5
